"""Batch job runner implementing the legacy error-handling semantics."""


def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run jobs sequentially and return an attempt log."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        retries = job["on_error"].get("retries", 0)
        attempts = 0
        succeeded = False

        max_attempts = retries + 1 if policy == "RETRY" else 1

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "ABORT" or attempts >= max_attempts:
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "abort",
                            "audits": [],
                        }
                    )
                    return run_log
            else:
                succeeded = True
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
